-- Updated to meet review requirements
-- Set lock and statement timeouts before any DDL
SET lock_timeout = '500ms';
SET statement_timeout = '1000ms';

-- Add column
ALTER TABLE orders ADD COLUMN status text;

-- Add a NOT VALID constraint to ensure only allowed values
ALTER TABLE orders ADD CONSTRAINT status_valid CHECK (
    status IN ('cancelled','refunded','partly_refunded','shipped','placed')
) NOT VALID;

-- Create a procedure that backfills status in batches
CREATE OR REPLACE PROCEDURE fill_status()
LANGUAGE plpgsql
AS $$
DECLARE
    batch_size bigint := 100000;
    start_id bigint := 0;
    max_id bigint;
BEGIN
    -- Determine the maximum id to bound the loop
    SELECT max(id) INTO max_id FROM orders;
    WHILE start_id < max_id LOOP
        UPDATE orders
        SET status = CASE
            WHEN cancelled_at IS NOT NULL THEN 'cancelled'
            WHEN refunded_cents > 0 AND refunded_cents >= total_cents THEN 'refunded'
            WHEN refunded_cents > 0 THEN 'partly_refunded'
            WHEN shipped_at IS NOT NULL THEN 'shipped'
            ELSE 'placed'
        END
        WHERE id > start_id AND id <= start_id + batch_size
          AND status IS NULL;
        COMMIT;
        start_id := start_id + batch_size;
    END LOOP;
END;
$$;

-- Run the procedure
CALL fill_status();

-- Drop the procedure after use
DROP PROCEDURE fill_status();

-- Validate the constraint (this will scan the table under SHARE UPDATE EXCLUSIVE)
ALTER TABLE orders VALIDATE CONSTRAINT status_valid;

-- Now we can safely set NOT NULL (catalogue change only)
ALTER TABLE orders ALTER COLUMN status SET NOT NULL;

-- Updated migration to meet review requirements
-- Set timeout for locks and statements before any DDL
SET lock_timeout = '1s';
SET statement_timeout = '700ms';

-- 1. Add the column
ALTER TABLE orders ADD COLUMN status text;

-- 2. Add a CHECK constraint that is NOT VALID to avoid an immediate scan
ALTER TABLE orders ADD CONSTRAINT status_valid CHECK (
    status IN ('cancelled','refunded','partly_refunded','shipped','placed')
) NOT VALID;

-- 3. Backfill the column in batches using a procedure that commits between batches
CREATE OR REPLACE PROCEDURE fill_status()
LANGUAGE plpgsql
AS $$
DECLARE
    batch_size bigint := 5000;          -- batch size small enough to fit in 750ms
    start_id bigint := 0;
    max_id bigint;
BEGIN
    SELECT max(id) INTO max_id FROM orders;
    WHILE start_id < max_id LOOP
        LOOP
            BEGIN
                UPDATE orders
                SET status = CASE
                    WHEN cancelled_at IS NOT NULL THEN 'cancelled'
                    WHEN refunded_cents > 0 AND refunded_cents >= total_cents THEN 'refunded'
                    WHEN refunded_cents > 0 THEN 'partly_refunded'
                    WHEN shipped_at IS NOT NULL THEN 'shipped'
                    ELSE 'placed'
                END
                WHERE id > start_id AND id <= start_id + batch_size
                  AND status IS NULL;
                COMMIT;
                EXIT; -- success
            EXCEPTION
                WHEN SQLSTATE '55P03' OR SQLSTATE '57014' THEN
                    -- lock conflict or statement timeout: wait a bit and retry
                    PERFORM pg_sleep(0.1);
            END;
        END LOOP;
        start_id := start_id + batch_size;
    END LOOP;
END;
$$;

-- Execute the backfill procedure
CALL fill_status();

-- Drop the temporary procedure
DROP PROCEDURE fill_status();

-- 4. Validate the CHECK constraint (uses SHARE UPDATE EXCLUSIVE lock, not ACCESS EXCLUSIVE)
ALTER TABLE orders VALIDATE CONSTRAINT status_valid;

-- 5. Set the column to NOT NULL (catalogue change only, no table rewrite)
ALTER TABLE orders ALTER COLUMN status SET NOT NULL;
